  function htmlEscape(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function hasUiPlaceholderToken(value) {
    const text = String(value === undefined || value === null ? '' : value).trim();
    return !!text && /待补全|待生成|未知|未详|不详/i.test(text);
  }

  function toText(value, fallback = '无') {
    if (value === undefined || value === null || value === '') return fallback;
    const text = String(value);
    return hasUiPlaceholderToken(text) ? fallback : text;
  }


  function toNumber(value, fallback = 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }

  function toMultiplierValue(value, fallback = 1) {
    const text = String(value ?? '').trim();
    if (/%$/.test(text)) {
      const parsed = Number(text.replace('%', ''));
      if (!Number.isFinite(parsed)) return fallback;
      return /^[+-]/.test(text) ? 1 + parsed / 100 : parsed / 100;
    }
    return toNumber(value, fallback);
  }

  function 解析带符号比例数值(value, fallback = 0) {
    const 文本 = String(value ?? '').trim();
    if (!文本) return fallback;
    if (/%$/.test(文本)) {
      const 数值 = Number(文本.replace('%', ''));
      return Number.isFinite(数值) ? 数值 / 100 : fallback;
    }
    return toNumber(value, fallback);
  }

  function 计算稳定哈希数值_桥接(文本 = '') {
    let 哈希 = 2166136261;
    String(文本 || '').split('').forEach(字符 => {
      哈希 ^= 字符.charCodeAt(0);
      哈希 += (哈希 << 1) + (哈希 << 4) + (哈希 << 7) + (哈希 << 8) + (哈希 << 24);
    });
    return 哈希 >>> 0;
  }

  function 读取稳定随机数_桥接(文本 = '') {
    return (计算稳定哈希数值_桥接(文本) % 10000) / 10000;
  }

