    if (目标消息元信息 && !目标AI楼层仍匹配_桥接(目标消息元信息)) return { changed: false, reason: 'target_changed' };
    const 归档选项 = 目标消息元信息
      ? { ...(选项 && typeof 选项 === 'object' ? 选项 : {}), 目标消息元信息, message_id: 目标消息元信息.消息编号, 消息编号: 目标消息元信息.消息编号, 楼层: 目标消息元信息.消息索引, 禁止目标回退: true }
      : 选项;
