          const 群体 = !对象 && ['talk', 'intel', 'brief'].includes(动作);
          if ((!对象 && !群体) || !['talk', 'intel', 'brief', 'battle', 'trade', 'commission'].includes(动作)) return { ok: false, message: '互动参数不完整。' };
