          const { 旧名, 新名, 分类, 定义 } = 结果, 数量 = Math.max(0, Math.floor(toNumber(参数.qty, 0)));
          const 角色键 = resolveSnapshotCharKey(liveSnapshot, toText(liveSnapshot && liveSnapshot.activeName, '')) || toText(liveSnapshot && liveSnapshot.activeName, '');
