      independentRing: (角色, 武魂槽, 魂环槽, 魂技键, label) => ({ path: ['char', 角色, 武魂槽, 魂环槽, 魂技键], label: label || 魂技键, category: '独立魂环魂技', scope: 'independent_ring_skill' }),
