    const hl = hr ? hr.left - cr.left : 0, hrt = hr ? hr.right - cr.left : 0, room = Math.floor(host?.dataset.float === 'l' ? hl : host?.dataset.float === 'r' ? cr.width - hrt : Math.max(cr.width - hrt, hl)) - 28;
